1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x1, y1]: Cell, [x2, y2]: Cell): boolean => x1 === x2 && y1 === y2;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
17	  neighborsOf(cell).filter((neighbor) => isLive(neighbor, liveCells)).length;
18	
19	const survives = (cell: Cell, liveCells: Cell[]): boolean => {
20	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
21	  return liveNeighbors === 2 || liveNeighbors === 3;
22	};
23	
24	const containsCell = (cells: Cell[], cell: Cell): boolean =>
25	  cells.some((other) => isSameCell(other, cell));
26	
27	const isLive = (cell: Cell, liveCells: Cell[]): boolean => containsCell(liveCells, cell);
28	
29	const distinctCells = (cells: Cell[]): Cell[] =>
30	  cells.filter((cell, index) => !containsCell(cells.slice(0, index), cell));
31	
32	const candidateCells = (liveCells: Cell[]): Cell[] =>
33	  distinctCells([...liveCells, ...liveCells.flatMap(neighborsOf)]);
34	
35	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
36	  candidateCells(liveCells).filter((cell) =>
37	    isLive(cell, liveCells)
38	      ? survives(cell, liveCells)
39	      : countLiveNeighbors(cell, liveCells) === 3,
40	  );
